-- V3__import_agmarknet_mandis.sql
-- Full official Agmarknet Mandis dataset import (4,121 procurement centres across all 36 Indian States/UTs)

ALTER TABLE centers ADD COLUMN IF NOT EXISTS market_id INTEGER;
ALTER TABLE centers ADD COLUMN IF NOT EXISTS state_id INTEGER;
ALTER TABLE centers ADD COLUMN IF NOT EXISTS district_id INTEGER;
ALTER TABLE centers ADD COLUMN IF NOT EXISTS classification VARCHAR(50) DEFAULT 'APMC (Regulated)';

CREATE INDEX IF NOT EXISTS idx_centers_state_district ON centers(state, district);
CREATE INDEX IF NOT EXISTS idx_centers_classification ON centers(classification);
CREATE INDEX IF NOT EXISTS idx_centers_market_id ON centers(market_id);

-- Update pre-existing demo centers with Agmarknet classifications
UPDATE centers SET market_id = 99001, state_id = 28, district_id = 1001, classification = 'Grain Market' WHERE code = 'PUN001';
UPDATE centers SET market_id = 99002, state_id = 28, district_id = 1002, classification = 'APMC (Regulated)' WHERE code = 'PUN002';
UPDATE centers SET market_id = 99003, state_id = 28, district_id = 1001, classification = 'Principal Yard' WHERE code = 'PUN003';
UPDATE centers SET market_id = 99004, state_id = 20, district_id = 2001, classification = 'APMC (Regulated)' WHERE code = 'CTA';
UPDATE centers SET market_id = 99005, state_id = 20, district_id = 2001, classification = 'Sub Yard' WHERE code = 'CTB';
UPDATE centers SET market_id = 99006, state_id = 20, district_id = 2001, classification = 'Principal Yard' WHERE code = 'CTC';
UPDATE centers SET market_id = 99007, state_id = 34, district_id = 3001, classification = 'Grain Market' WHERE code = 'UP001';
UPDATE centers SET market_id = 99008, state_id = 12, district_id = 4001, classification = 'Grain Market' WHERE code = 'HR001';

ON CONFLICT (code) DO UPDATE SET
  market_id = EXCLUDED.market_id,
  state_id = EXCLUDED.state_id,
  district_id = EXCLUDED.district_id,
  classification = EXCLUDED.classification;

